-- Версия 1.0.0 — первый стабильный выпуск. Повторный запуск безопасен (если версия уже есть, ничего не меняется).
-- Пункты видны по уровню (min_rank): 1 все, 2 админы по предметам и выше, 3 админы и выше, 4 только главный админ.
select public.add_site_release('1.0.0','🎉 Экзаменатор 1.0 — первый стабильный выпуск',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','🎉 Версия 1.0: банк вопросов, генератор билетов, архив наборов, чат-бот и мини-приложение собраны в одну надёжную систему — спасибо, что работаете с нами!'),
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','🛡 Перед выпуском проверили всё: безопасность, права доступа, работу на телефонах, тёмную тему и каждый раздел сайта.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','📱 Сайт стал удобнее на телефоне: страницы больше не уезжают вбок, кнопки и поля крупнее и читаются в любой теме.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','⌨️ Окна и нижнее меню закрываются клавишей Esc, управляются с клавиатуры, а при настройке «уменьшить движение» анимации отключаются сами.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Вход: при неверном пароле форма больше не очищается и подсказывает, что не так.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','После выхода следующий человек за этим компьютером не видит чужие данные и последний набор билетов.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Генератор: карточка «Готово» всегда скачивает актуальный состав набора, даже если его правили в «Архиве билетов».'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Банк вопросов: при листании страниц вопросы не повторяются и не пропадают, а устаревшие фильтры сбрасываются сами.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Кнопка «Привязать другой чат» в окне Telegram снова выдаёт код и ссылку.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',2,'text','Форма вопроса: новый вопрос не сохранится в удалённую тему, а картинки не теряются, если нажать «Сохранить» во время загрузки.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',2,'text','Массовый импорт: вопросы не попадают в чужую главу, новая тема не создаётся дважды, а рисунки EMF/WMF из Word больше не становятся битыми картинками.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',2,'text','Качество банка: во время проверки нельзя переключить предмет, результаты разных предметов не смешиваются.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',3,'text','Корзина: вопрос из удалённой темы нельзя вернуть так, чтобы он незаметно попадал в билеты; откатанные партии показывают дату удаления.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',4,'text','Архив билетов: удалённый набор не возвращается, а кнопка «Отменить» не остаётся на экране, когда удаление уже выполнено.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',4,'text','Экзамен-кластер: после смены набора или предмета книжка не собирается из прежнего набора; вопросы к тексту не попадают в книжку без текста.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',4,'text','Своя игра: экран команды не откатывается назад при медленной связи, а команда не вылетает из игры из-за устаревшего ответа.'),
    jsonb_build_object('kind','fixed','scope','app','min_rank',1,'text','Проверка бланков: живая камера работает и не перезапускается после каждого снимка; двойное нажатие не добавляет один бланк дважды.'),
    jsonb_build_object('kind','fixed','scope','app','min_rank',1,'text','Мини-приложение: двойное нажатие «Создать и отправить» не создаёт два набора, при обрыве связи появилась кнопка «Повторить».'),
    jsonb_build_object('kind','fixed','scope','bot','min_rank',1,'text','Бот: главы и темы со знаками < > & в названии больше не останавливают пошаговый выбор.'),
    jsonb_build_object('kind','fixed','scope','bot','min_rank',4,'text','Безопасность: роль «Учитель игры» не получает вопросы банка через бота и мини-приложение, а новый пользователь не создаётся с лишними правами, если роль не применилась.')
  ),
  '2026-11-22 03:30:00+05');
